import csv
D="/home/claude/emst/docs/research/state-local/"
codes={r["code"] for r in csv.DictReader(open("/home/claude/emst/data/v1_baseline/competencies.csv"))}
def W(name,H,R,codecol=None):
    with open(D+name,"w",newline="",encoding="utf-8") as f:
        w=csv.writer(f); w.writerow(H)
        for r in R:
            assert len(r)==len(H),(name,r[0],len(r))
            if codecol is not None:
                for c in r[codecol].split("|"):
                    assert (not c) or c in codes,(r[0],c)
            w.writerow(r)
    print(name,len(R))
